// Card data generated by pipeline/build_data.py (src/data/*.json — do not edit by hand)
import cardsJson from '../data/cards.json'
import tokensJson from '../data/tokens.json'
import kwJson from '../data/keywords.json'
import archJson from '../data/archetypes.json'
import plblJson from '../data/pairLabels.json'
import ctipsJson from '../data/cardTips.json'
import metaJson from '../data/meta.json'
import type { AnyCard, Archetypes, Card, CardTips, Keyword, Token } from '../types'
import { searchKey } from './search'
import { FAC_ORDER } from './constants'

export const CARDS = cardsJson as unknown as Card[]
export const TOK = tokensJson as unknown as Record<string, Token>
export const KW = kwJson as unknown as Record<string, Keyword>
export const ARCH = archJson as unknown as Archetypes
export const PLBL = plblJson as unknown as Record<string, string>
export const CTIPS = ctipsJson as unknown as CardTips
export const META = metaJson as { ver: string; count: number; hasKwTh: boolean }
export const HAS_KWTH = META.hasKwTh

export const BYID: Record<number, Card> = {}
CARDS.forEach(c => { BYID[c.id] = c })
export const getCard = (id: number): AnyCard | undefined => BYID[id] || TOK[id]

/** lower-cased search haystack per card id (name + EN/TH ability + tags + type + faction) */
export const SKEY = new Map<number, string>(CARDS.map(c => [c.id, searchKey(c)]))
/** faction sort index per card id */
export const FO = new Map<number, number>(CARDS.map(c => [c.id, FAC_ORDER.indexOf(c.f)]))
/** all distinct provision values, ascending (provision range selects) */
export const PROVS = [...new Set(CARDS.map(c => c.v))].sort((a, b) => a - b)

export const hasTip = (id: number) => !!(CTIPS && CTIPS[id] && (CTIPS[id].tips || []).length)

import { fmtAb2, makeKwRe } from './keywords'
/** keyword matcher built from all keyword names */
export const KWRE = makeKwRe(Object.keys(KW))
/** ability text → HTML (bold labels + keyword popover buttons) */
export const abHTML = (s: string) => fmtAb2(s, KWRE)
